## 三、代码示例与详细注释

### 3.1 分块矩阵乘法内核

以下代码展示了使用共享内存的分块矩阵乘法实现，包含详细注释：

```cuda
// 分块矩阵乘法内核
// 使用共享内存减少全局内存访问
__global__ void matrixMulTiled(float *M, float *N, float *P, int Width) {
    // 声明共享内存数组，用于存储M和N的块
    // 每个块有独立的Mds和Nds实例
    __shared__ float Mds[TILE_WIDTH][TILE_WIDTH];
    __shared__ float Nds[TILE_WIDTH][TILE_WIDTH];

    // 将threadIdx和blockIdx保存到寄存器变量
    // 这些变量是线程私有的，存储在寄存器中
    int tx = threadIdx.x;  // 块内线程的x索引
    int ty = threadIdx.y;  // 块内线程的y索引
    int bx = blockIdx.x;   // 块的x索引
    int by = blockIdx.y;   // 块的y索引

    // 计算线程负责计算的P矩阵元素的行列索引
    // 每个块覆盖TILE_WIDTH个元素
    int Row = by * TILE_WIDTH + ty;  // P元素的行索引
    int Col = bx * TILE_WIDTH + tx;  // P元素的列索引

    // 用于累加点积的寄存器变量
    // 每个线程有私有的Pvalue实例
    float Pvalue = 0.0f;

    // 循环遍历所有阶段
    // 每个阶段处理一个M块和一个N块
    for (int ph = 0; ph < Width / TILE_WIDTH; ++ph) {
        // 协作加载M块到共享内存
        // 每个线程加载一个M元素
        // Row是行索引，ph*TILE_WIDTH+tx是列索引
        Mds[ty][tx] = M[Row * Width + ph * TILE_WIDTH + tx];

        // 协作加载N块到共享内存
        // ph*TILE_WIDTH+ty是行索引，Col是列索引
        Nds[ty][tx] = N[(ph * TILE_WIDTH + ty) * Width + Col];

        // 屏障同步：确保所有线程完成加载
        // 这是读后写依赖，必须等待数据写入完成
        __syncthreads();

        // 执行当前阶段的点积累加
        // 使用共享内存中的数据进行计算
        for (int k = 0; k < TILE_WIDTH; ++k) {
            Pvalue += Mds[ty][k] * Nds[k][tx];
        }

        // 屏障同步：确保所有线程完成读取
        // 这是写后读依赖，必须等待数据读取完成
        // 防止下一阶段加载覆盖当前阶段的数据
        __syncthreads();
    }

    // 将最终结果写入全局内存
    P[Row * Width + Col] = Pvalue;
}
```

**代码解析**：

1. **共享内存声明**：`Mds`和`Nds`是共享内存数组，每个线程块有独立的实例。大小为`TILE_WIDTH × TILE_WIDTH`，足以存储一个输入块。

2. **索引计算**：每个线程根据其块索引和线程索引计算负责的输出元素位置。这种计算方式确保输出矩阵的每个元素恰好由一个线程计算。

3. **阶段循环**：点积计算被划分为多个阶段，每个阶段处理一个块的数据。阶段数等于`Width / TILE_WIDTH`。

4. **协作加载**：块内所有线程协作加载输入数据。每个线程加载一个M元素和一个N元素到共享内存。通过`tx`和`ty`的索引组合，确保所有元素被唯一加载。

5. **屏障同步**：两次`__syncthreads()`调用确保正确的数据依赖关系。第一次确保数据加载完成，第二次确保数据使用完成。

6. **点积计算**：使用共享内存中的数据进行乘加运算。注意访问模式：`Mds[ty][k]`访问M块的行，`Nds[k][tx]`访问N块的列。

### 3.2 带边界检查的分块矩阵乘法

当矩阵宽度不是TILE_WIDTH的倍数时，需要添加边界检查：

```cuda
__global__ void matrixMulTiledWithBoundary(float *M, float *N, float *P, int Width) {
    __shared__ float Mds[TILE_WIDTH][TILE_WIDTH];
    __shared__ float Nds[TILE_WIDTH][TILE_WIDTH];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    int Row = by * TILE_WIDTH + ty;
    int Col = bx * TILE_WIDTH + tx;

    float Pvalue = 0.0f;

    // 循环遍历所有阶段
    for (int ph = 0; ph < (Width + TILE_WIDTH - 1) / TILE_WIDTH; ++ph) {
        // 加载M块的边界检查
        // 检查行索引和列索引是否在有效范围内
        if (Row < Width && (ph * TILE_WIDTH + tx) < Width) {
            Mds[ty][tx] = M[Row * Width + ph * TILE_WIDTH + tx];
        } else {
            // 超出边界时填充0，不影响点积结果
            Mds[ty][tx] = 0.0f;
        }

        // 加载N块的边界检查
        if ((ph * TILE_WIDTH + ty) < Width && Col < Width) {
            Nds[ty][tx] = N[(ph * TILE_WIDTH + ty) * Width + Col];
        } else {
            Nds[ty][tx] = 0.0f;
        }

        __syncthreads();

        // 只有当阶段在有效范围内时才进行计算
        if (ph * TILE_WIDTH < Width) {
            for (int k = 0; k < TILE_WIDTH; ++k) {
                Pvalue += Mds[ty][k] * Nds[k][tx];
            }
        }

        __syncthreads();
    }

    // 只有负责有效P元素的线程才写入结果
    if (Row < Width && Col < Width) {
        P[Row * Width + Col] = Pvalue;
    }
}
```

**边界检查要点**：

1. **加载检查**：每次从全局内存加载数据前，检查索引是否在矩阵范围内。超出范围时填充0，避免访问非法内存。

2. **计算检查**：确保只在有效阶段进行计算，避免使用无效数据。

3. **存储检查**：只有负责有效输出元素的线程才写入结果，避免覆盖其他数据。

### 3.3 动态共享内存分配

当需要根据设备能力动态调整共享内存大小时，使用动态分配：

```cuda
// 使用extern关键字声明动态共享内存
extern __shared__ float sharedMemory[];

__global__ void matrixMulDynamicShared(float *M, float *N, float *P, 
                                        int Width, 
                                        int MdsSize, int NdsSize) {
    // 手动划分共享内存区域
    // Mds从sharedMemory起始位置开始
    float *Mds = sharedMemory;
    // Nds从Mds之后开始
    float *Nds = &sharedMemory[MdsSize / sizeof(float)];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    int Row = by * TILE_WIDTH + ty;
    int Col = bx * TILE_WIDTH + tx;

    float Pvalue = 0.0f;

    for (int ph = 0; ph < Width / TILE_WIDTH; ++ph) {
        // 使用线性化索引访问共享内存
        // 替代Mds[ty][tx]，使用Mds[ty * TILE_WIDTH + tx]
        Mds[ty * TILE_WIDTH + tx] = M[Row * Width + ph * TILE_WIDTH + tx];
        Nds[ty * TILE_WIDTH + tx] = N[(ph * TILE_WIDTH + ty) * Width + Col];

        __syncthreads();

        for (int k = 0; k < TILE_WIDTH; ++k) {
            Pvalue += Mds[ty * TILE_WIDTH + k] * Nds[k * TILE_WIDTH + tx];
        }

        __syncthreads();
    }

    P[Row * Width + Col] = Pvalue;
}

// 主机端调用示例
void launchKernel(float *M, float *N, float *P, int Width) {
    dim3 dimBlock(TILE_WIDTH, TILE_WIDTH);
    dim3 dimGrid((Width + TILE_WIDTH - 1) / TILE_WIDTH, 
                 (Width + TILE_WIDTH - 1) / TILE_WIDTH);

    // 计算所需的共享内存大小（字节）
    size_t sharedMemSize = 2 * TILE_WIDTH * TILE_WIDTH * sizeof(float);

    // 启动内核，第三个参数是动态共享内存大小
    matrixMulDynamicShared<<<dimGrid, dimBlock, sharedMemSize>>>(
        M, N, P, Width, 
        TILE_WIDTH * TILE_WIDTH * sizeof(float),  // Mds大小
        TILE_WIDTH * TILE_WIDTH * sizeof(float)   // Nds大小
    );
}
```

**动态分配优势**：

1. **灵活性**：根据设备查询结果动态调整共享内存使用量
2. **可移植性**：同一内核可在不同设备上运行，自动适应硬件限制
3. **资源优化**：充分利用设备的共享内存资源

### 3.4 内存合并优化示例

展示如何优化访问模式以实现内存合并：

```cuda
// 非合并访问模式（低效）
__global__ void matrixMulUncoalesced(float *M, float *N, float *P, int Width) {
    int Row = blockIdx.y * blockDim.y + threadIdx.y;
    int Col = blockIdx.x * blockDim.x + threadIdx.x;

    if (Row < Width && Col < Width) {
        float Pvalue = 0.0f;

        // 访问M的行：连续线程访问连续列，可以合并
        // 访问N的列：连续线程访问跨步Width的位置，无法合并
        for (int k = 0; k < Width; ++k) {
            Pvalue += M[Row * Width + k] * N[k * Width + Col];
        }

        P[Row * Width + Col] = Pvalue;
    }
}

// 合并访问模式（高效）- 使用分块技术
__global__ void matrixMulCoalesced(float *M, float *N, float *P, int Width) {
    __shared__ float Mds[TILE_WIDTH][TILE_WIDTH];
    __shared__ float Nds[TILE_WIDTH][TILE_WIDTH];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    int Row = by * TILE_WIDTH + ty;
    int Col = bx * TILE_WIDTH + tx;

    float Pvalue = 0.0f;

    for (int ph = 0; ph < Width / TILE_WIDTH; ++ph) {
        // 加载M块：连续线程（tx递增）访问连续地址
        // Row相同，ph*TILE_WIDTH+tx递增 -> 合并访问
        int M_col = ph * TILE_WIDTH + tx;
        Mds[ty][tx] = M[Row * Width + M_col];

        // 加载N块：连续线程（tx递增）访问连续地址
        // ph*TILE_WIDTH+ty相同，Col递增 -> 合并访问
        int N_row = ph * TILE_WIDTH + ty;
        Nds[ty][tx] = N[N_row * Width + Col];

        __syncthreads();

        for (int k = 0; k < TILE_WIDTH; ++k) {
            Pvalue += Mds[ty][k] * Nds[k][tx];
        }

        __syncthreads();
    }

    P[Row * Width + Col] = Pvalue;
}
```

**合并访问分析**：

1. **M块加载**：对于同一warp中的线程，`Row`相同（ty相同），`tx`递增，因此`M[Row * Width + ph * TILE_WIDTH + tx]`访问连续地址，实现合并。

2. **N块加载**：对于同一warp中的线程，`ph * TILE_WIDTH + ty`相同（ty相同），`Col`递增（tx递增），因此`N[(ph * TILE_WIDTH + ty) * Width + Col]`访问连续地址，实现合并。

3. **关键技巧**：通过分块和数据重排，将原本跨步访问的N矩阵列访问转换为连续访问。

